def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    if n < 2:
        return n
    # Newton's method, starting from a float approximation. The initial guess
    # is never smaller than the true root, so the integer iterates descend
    # monotonically and terminate at the floor of the square root.
    x = int(n ** 0.5)
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    return x

def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    if n < 2:
        return n
    # Newton's method using exact integer arithmetic. The initial guess is
    # rounded up, so the integer iterates descend monotonically and terminate
    # at the largest integer whose square is <= n.
    x = int(n ** 0.5)
    while True:
        if x * x > n:
            x = (x + n // x) // 2
        else:
            break
    return x

