cd /work && python3 - <<'EOF'
import sys
sys.path.insert(0, '/work')
from sqrt_int import sqrt_int

def check(n):
    result = sqrt_int(n)
    assert type(result) is int, "result must be a plain int, got %r" % (result,)
    square = int(result) * int(result)
    assert type(square) is int and square == n, (
        "%d is not the exact integer square root of %d" % (result, n)
    )

try:
    check(0)
except AssertionError as e:
    print("check(0) raised:", e)
try:
    check(1)
except AssertionError as e:
    print("check(1) raised:", e)
try:
    check(4)
except AssertionError as e:
    print("check(4) raised:", e)
try:
    check(9)
except AssertionError as e:
    print("check(9) raised:", e)
try:
    check(144)
except AssertionError as e:
    print("check(144) raised:", e)
try:
    check(2)
except AssertionError as e:
    print("check(2) raised:", e)
EOF
